from __future__ import annotations

from ..contracts import Health, RuntimeContext, ServiceSpec, ServiceState
from ..registry.graph import NodeRegistryService


class HealthCoordinator:
    spec = ServiceSpec(
        "operations.health",
        required=True,
        dependencies=("interfaces.ingress", "registry.graph"),
    )

    def __init__(self) -> None:
        self._context: RuntimeContext | None = None
        self._state = ServiceState.DECLARED

    async def start(self, context: RuntimeContext) -> None:
        self._context = context
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._state = ServiceState.STOPPED
        self._context = None

    async def health(self) -> Health:
        return Health(self._state)

    async def snapshot(self) -> dict:
        if self._context is None:
            raise RuntimeError("health_coordinator_not_ready")
        statuses = await self._context.status()  # type: ignore[attr-defined]
        required: set[str] = set()
        try:
            registry = self._context.get_service("registry.graph")
            if isinstance(registry, NodeRegistryService):
                required = {
                    str(row.get("name"))
                    for row in registry.snapshot().get("nodes", [])
                    if isinstance(row, dict) and row.get("required") is True
                }
        except Exception:
            required = set()
        failed = sorted(
            name for name, health in statuses.items()
            if health.state == ServiceState.FAILED
        )
        degraded = sorted(
            name for name, health in statuses.items()
            if health.state == ServiceState.DEGRADED
        )
        required_failures = sorted(name for name in failed if name in required)
        return {
            "ok": not required_failures,
            "services": {
                name: {"state": health.state.value, "detail": health.detail}
                for name, health in sorted(statuses.items())
            },
            "failed_services": failed,
            "degraded_services": degraded,
            "required_failures": required_failures,
            "required_service_count": len(required),
        }
